    [StructLayout(LayoutKind.Explicit, Size = 8)]
    struct DfbSaveDone
    {
        [FieldOffset(0)] public uint txn;
        [FieldOffset(4)] public uint committed;  // 1 if the bundle replaced the save file
    }

    [StructLayout(LayoutKind.Explicit, Size = 16)]
    struct DfbHello
    {
        [FieldOffset(0)] public uint pid;
        [FieldOffset(4)] public uint side;
        [FieldOffset(8)] public long nowNs;
    }

    [StructLayout(LayoutKind.Explicit, Size = 256)]
    struct DfbDfState
    {
        [FieldOffset(0)] public uint publishSeq;  // stamped by dfb_publish_state
        [FieldOffset(4)] public uint dfPhase;
        [FieldOffset(8)] public ulong dfHeartbeat;  // increments every Daggerfall frame
        [FieldOffset(16)] public long publishedNs;  // stamped by dfb_publish_state
        [FieldOffset(24)] public uint dfFrame;
        [FieldOffset(28)] public uint demoValue;  // bridge demo only: a value Daggerfall changes for Doom to read
        [FieldOffset(32)] public int hpCurrent;  // Daggerfall's confirmed player HP; meaningful when DFB_HPF_VALID is set
        [FieldOffset(36)] public int hpMax;
        [FieldOffset(40)] public uint hpAppliedEvent;  // event_no of the last dfb_hp_event Daggerfall applied
        [FieldOffset(44)] public uint hpFlags;  // DFB_HPF_*
        [FieldOffset(48)] public int damageBonusBp;
        [FieldOffset(52)] public uint playerFlags;  // DFB_PLF_*: Daggerfall's falling damage exemptions, which Doom applies to its falls
        // 200 reserved bytes at offset 56
    }

    [StructLayout(LayoutKind.Explicit, Size = 256)]
    struct DfbUzState
    {
        [FieldOffset(0)] public uint publishSeq;
        [FieldOffset(4)] public uint uzPhase;
        [FieldOffset(8)] public ulong uzHeartbeat;  // increments every UZDoom frame
        [FieldOffset(16)] public long publishedNs;
        [FieldOffset(24)] public uint uzTic;  // gametic
        [FieldOffset(28)] public uint demoValue;  // bridge demo only
        [FieldOffset(32)] public double worldX;  // player position in Daggerfall world units: doom / 0.75 + window origin
        [FieldOffset(40)] public double worldZ;  // Daggerfall's north axis, which is Doom's +Y
        [FieldOffset(48)] public double worldHeight;  // Daggerfall units; informational, Daggerfall stands on its own terrain
        [FieldOffset(56)] public float yawDegrees;  // Doom angle: 0 is east, counterclockwise
        [FieldOffset(60)] public uint worldContext;  // DFB_WORLD_*
        [FieldOffset(64)] public int mapPixelX;
        [FieldOffset(68)] public int mapPixelY;  // Daggerfall convention: 499 - floor(world_z / 32768)
        [FieldOffset(72)] public uint areaSeq;  // increments with each DFB_KIND_AREA
        [FieldOffset(76)] public uint pad0;
        [FieldOffset(80)] public double spaceX;
        [FieldOffset(88)] public double spaceY;
        [FieldOffset(96)] public double spaceZ;
        [FieldOffset(104)] public float spaceYaw;  // Doom angle within the space
        [FieldOffset(108)] public int spaceTarget;  // the target of the door event for this space
        [FieldOffset(112)] public uint spaceValid;  // 0 outdoors and between maps
        [FieldOffset(116)] public uint pad1;
        // 136 reserved bytes at offset 120
    }

    [StructLayout(LayoutKind.Explicit, Size = 56)]
    struct DfbStats
    {
        [FieldOffset(0)] public ulong sent;  // events accepted by dfb_send
        [FieldOffset(8)] public ulong received;  // events returned by dfb_receive
        [FieldOffset(16)] public ulong queuedOverflow;  // events that went through the outbox
        [FieldOffset(24)] public ulong seqGaps;  // received events whose seq skipped a value
        [FieldOffset(32)] public uint outboxCount;  // events waiting in the outbox
        [FieldOffset(36)] public uint outboxPeak;
        [FieldOffset(40)] public uint ringUsedOut;  // events in our outgoing ring not yet read by the peer
        [FieldOffset(44)] public uint ringUsedIn;  // events in our incoming ring not yet read by us
        [FieldOffset(48)] public uint peerPid;  // pid of the attached peer, 0 if none or it closed cleanly
        [FieldOffset(52)] public uint peerAttachCount;
    }

    static class DfbNative
    {
        const string Dll = "doomerfall_bridge";

        [DllImport(Dll)] public static extern uint dfb_protocol_version();
        [DllImport(Dll)] public static extern ulong dfb_layout_hash();
        [DllImport(Dll)] public static extern ulong dfb_schema_hash();
        [DllImport(Dll)] public static extern uint dfb_struct_size(int which);
        [DllImport(Dll)] public static extern long dfb_now_ns();
        [DllImport(Dll)] public static extern int dfb_create([MarshalAs(UnmanagedType.LPStr)] string sessionId, out IntPtr @out);
        [DllImport(Dll)] public static extern int dfb_attach([MarshalAs(UnmanagedType.LPStr)] string sessionId, int side, out IntPtr @out);
        [DllImport(Dll)] public static extern void dfb_close(IntPtr session);
        [DllImport(Dll)] public static extern int dfb_send(IntPtr session, ref DfbEvent @event);
        [DllImport(Dll)] public static extern int dfb_flush(IntPtr session);
        [DllImport(Dll)] public static extern int dfb_receive(IntPtr session, ref DfbEvent @out);
        [DllImport(Dll)] public static extern int dfb_publish_state(IntPtr session, ref DfbDfState state, uint size);
        [DllImport(Dll)] public static extern int dfb_read_state(IntPtr session, ref DfbUzState @out, uint size);
        [DllImport(Dll)] public static extern int dfb_bulk_write(IntPtr session, uint slot, byte[] data, uint size, out uint versionOut);
        [DllImport(Dll)] public static extern int dfb_bulk_read(IntPtr session, uint slot, byte[] @out, uint capacity, out uint sizeOut, out uint versionOut);
        [DllImport(Dll)] public static extern uint dfb_bulk_version(IntPtr session, uint slot);
        [DllImport(Dll)] public static extern int dfb_surface_write(IntPtr session, byte[] bgra, uint width, uint height, uint frameId, long capturedNs, long inputNs, int flipY);
        [DllImport(Dll)] public static extern int dfb_get_stats(IntPtr session, ref DfbStats @out);
        [DllImport(Dll)] public static extern int dfb_atomic_replace([MarshalAs(UnmanagedType.LPStr)] string tempPath, [MarshalAs(UnmanagedType.LPStr)] string finalPath);
        [DllImport(Dll)] public static extern long dfb_peer_state_age_ns(IntPtr session);

        // Not imported, because their pointers have no safe C# form: dfb_surface_acquire
    }
}
